mapper.select:
select id, activity_id, member_id, balance, total_granted, total_consumed, create_time, update_time
from biz_lottery_chance
where activity_id = #{activityId} and member_id = #{memberId}

mapper.insert:
insert into biz_lottery_chance (
    activity_id, member_id, balance, total_granted, total_consumed, create_time, update_time
) values (
    #{activityId}, #{memberId}, #{balance}, #{totalGranted}, #{totalConsumed}, sysdate(), sysdate()
)

mapper.update:
update biz_lottery_chance
set balance = balance + #{amount},
    total_consumed = case
        when total_consumed >= #{amount} then total_consumed - #{amount}
        else 0
    end,
    update_time = sysdate()
where activity_id = #{activityId} and member_id = #{memberId}
